-module('formata_yamerl_SUITE_parsing_ex_5.12_tabs_and_spaces').

-include_lib("eunit/include/eunit.hrl").

-define(FILENAME, "test/fixtures/yamerl/parsing/ex_5.12_tabs_and_spaces.yaml").

single_test_() ->
    ?_assertMatch(
      {formata_yamerl_parser,
        {file,?FILENAME},
        [],
        <<>>,
        96,
        true,
        [],
        0,
        97,
        7,
        1,
        false,
        7,
        1,
        utf8,
        false,
        undefined,
        _,
        _,
        [],
        {bcoll,root,0,-1,1,1,-1,1,1},
        false,
        false,
        false,
        [{impl_key,false,false,undefined,undefined,1,1}],
        false,
        false,
        _,
        [],
        0,
        15,
        14,
        undefined,
        undefined,
        _,
        false,
        [],
        [
          {formata_yamerl_stream_end,7,1},
          {formata_yamerl_doc_end,7,1},
          {formata_yamerl_collection_end,7,1,block,mapping},
          {formata_yamerl_scalar,3,8,
            {formata_yamerl_tag,3,8,{non_specific,"!"}},
            block,literal,"void main() {\n\tprintf(\"Hello, world!\\n\");\n}\n"},
          {formata_yamerl_mapping_value,3,6},
          {formata_yamerl_scalar,3,1,
            {formata_yamerl_tag,3,1,{non_specific,"?"}},
            flow,plain,"block"},
          {formata_yamerl_mapping_key,3,1},
          {formata_yamerl_scalar,2,9,
            {formata_yamerl_tag,2,9,{non_specific,"!"}},
            flow,double_quoted,"Quoted \t"},
          {formata_yamerl_mapping_value,2,7},
          {formata_yamerl_scalar,2,1,
            {formata_yamerl_tag,2,1,{non_specific,"?"}},
            flow,plain,"quoted"},
          {formata_yamerl_mapping_key,2,1},
          {formata_yamerl_collection_start,2,1,
            {formata_yamerl_tag,2,1,{non_specific,"?"}},
            block,mapping},
          {formata_yamerl_doc_start,2,1,{1,2},_},
          {formata_yamerl_stream_start,1,1,utf8}
        ]
      },
      formata_yamerl_parser:file(?FILENAME)
    ).
